<template>
    <div
        class="sidebar"
        :data-color="userSettings.highlight"
        :data-background-color="userSettings.tint"
        :data-bs-theme="userSettings.tint === 'white' ? 'light' : 'dark'"
    >
        <div class="logo">
            <a href="/" class="simple-text logo-mini">
                <img v-if="logo" :src="logo" alt="" />
            </a>
            <a href="/" class="simple-text logo-normal">
                {{ appName }}
            </a>
        </div>
        <div class="sidebar-wrapper">
            <ul class="nav">
                <template v-for="(item, index) in navItems" :key="item.id">
                    <nav-panel-item
                        v-if="
                            (!item.roleRestriction ||
                                passesRoleRestriction(item.roleRestriction)) &&
                            (!item.permissionRestriction ||
                                passesPermissionRestriction(
                                    item.permissionRestriction,
                                ))
                        "
                        :title="item.title"
                        :icon="item.icon"
                        :url="item.url"
                        :active-url="item.activeUrl"
                        :sub-items="item.subItems"
                        :index="index"
                        :sub-item-type="item.subItemType"
                        :check-for-updates="item.checkForUpdates"
                        :show="item.show"
                    />
                </template>
                <nav-panel-item
                    v-if="$page.component === 'UserSettings/Index'"
                    title="Personīgie iestatījumi"
                    icon="settings"
                    :url="userSettingsUrl"
                    :index="navItems.length"
                />
            </ul>
            <!-- {{ $page.props.nav }} -->
        </div>
        <div
            v-if="userSettings.show_bg"
            class="sidebar-background"
            :style="{
                backgroundImage:
                    'url(' + backgroundImages[userSettings.background] + ')',
            }"
        ></div>
    </div>
</template>

<script>
import { ref } from 'vue';
import NavPanelItem from './NavPanelItem.vue';
import sidebar1 from '@scaffold-assets/sidebar-1.jpg';
import sidebar2 from '@scaffold-assets/sidebar-2.jpg';
import sidebar3 from '@scaffold-assets/sidebar-3.jpg';
import sidebar4 from '@scaffold-assets/sidebar-4.jpg';
import sidebar5 from '@scaffold-assets/sidebar-5.jpg';
import { index as userSettingsIndex } from '@app/routes/user-settings';

export default {
    name: 'NavPanel',
    inject: { scaffold: { default: () => ({}) } },
    components: {
        NavPanelItem,
    },
    data() {
        return {
            showingNavigationDropdown: ref(false),
            appName: import.meta.env.VITE_APP_NAME,
            userSettingsUrl: userSettingsIndex.url(),
            backgroundImages: [
                sidebar1,
                sidebar2,
                sidebar3,
                sidebar4,
                sidebar5,
            ],
            sidebarBackground: sidebar1,
        };
    },
    computed: {
        navItems() {
            return this.scaffold.navigation || [];
        },
        logo() {
            return this.scaffold.logo;
        },
        user() {
            return this.$page.props.auth.user;
        },
        userSettings() {
            return {
                highlight: this.user?.settings?.highlight || 'danger',
                tint: this.user?.settings?.tint || 'black',
                background: [0, 1, 2, 3, 4].includes(
                    parseInt(this.user?.settings?.background),
                )
                    ? this.user?.settings?.background
                    : 1,
                show_bg: this.user?.settings
                    ? this.user.settings?.show_bg
                    : true,
            };
        },
    },
    methods: {
        passesRoleRestriction(restriction) {
            if (Array.isArray(restriction)) {
                return restriction.some((role) => {
                    return this.$page.props.auth.roles[role] === true;
                });
            } else {
                return this.$page.props.auth.roles[restriction] === true;
            }
        },
        passesPermissionRestriction(restriction) {
            if (Array.isArray(restriction)) {
                return restriction.some((permission) => {
                    return (
                        this.$page.props.auth.permissions[permission] === true
                    );
                });
            } else {
                return this.$page.props.auth.permissions[restriction] === true;
            }
        },
    },
};
</script>

<style>
.nav .nav-item .nav-link {
    display: block;
}
</style>
