// InputPauseDirective.js
export default {
    name: 'paused-typing',
    beforeMount(el, binding) {
        let typingTimer;
        let doneTypingInterval = 700; // Adjust the delay as needed

        el.inputPauseEvent = function () {
            clearTimeout(typingTimer);
            typingTimer = setTimeout(() => {
                binding.value(); // Trigger the provided function when typing pauses
            }, doneTypingInterval);
        };

        el.addEventListener('input', el.inputPauseEvent);
    },
    unmounted(el) {
        // Remove the event listener when the bound element is unmounted
        el.removeEventListener('input', el.inputPauseEvent);
    },
};
