<template>
    <li
        v-if="!subItems && show"
        class="nav-item"
        :class="{ active: isActive(activeUrl || url) }"
    >
        <nav-link :href="resolveUrl(url)">
            <i class="material-icons">{{ icon }}</i>
            <p>{{ title }}</p>
        </nav-link>
    </li>

    <li
        v-else-if="subItemType === 'automatic' && show"
        class="nav-item"
        :class="{ active: isActive(activeUrl || url) }"
    >
        <a
            class="nav-link"
            data-bs-toggle="collapse"
            :href="'#nav-dropdown-' + index"
            :aria-expanded="isActive(activeUrl || url)"
        >
            <i class="material-icons">{{ icon }}</i>
            <p>
                {{ title }}
                <b class="caret"></b>
            </p>
        </a>

        <div
            class="collapse"
            :class="{ show: isActive(activeUrl || url) }"
            :id="'nav-dropdown-' + index"
        >
            <ul class="nav">
                <li
                    v-for="subItem in subItems"
                    :key="subItem.id"
                    class="nav-item"
                    :class="{ active: isActive(resolveUrl(url, subItem)) }"
                >
                    <Link class="nav-link" :href="resolveUrl(url, subItem)">
                        <span class="sidebar-mini">
                            <span class="material-icons">remove</span>
                        </span>

                        <span class="sidebar-normal pl-2">
                            {{ subItem.name }}

                            <template v-if="checkForUpdates">
                                <span v-if="subItem[checkForUpdates]" class="text-red">•</span>
                            </template>
                        </span>
                    </Link>
                </li>
            </ul>
        </div>
    </li>

    <li
        v-else-if="show"
        class="nav-item"
        :class="{ active: isActive(activeUrl || url) }"
    >
        <a
            class="nav-link"
            data-bs-toggle="collapse"
            :href="'#nav-dropdown-' + index"
            :aria-expanded="isActive(activeUrl || url)"
        >
            <i class="material-icons">{{ icon }}</i>
            <p>
                {{ title }}
                <b class="caret"></b>
            </p>
        </a>

        <div
            class="collapse"
            :class="{ show: isActive(activeUrl || url) }"
            :id="'nav-dropdown-' + index"
        >
            <ul class="nav">
                <template
                    v-for="(subItem, idx) in subItems"
                    :key="idx"
                >

                    <li
                        v-if="(!subItem.roleRestriction || passesRoleRestriction(subItem.roleRestriction)) && (!subItem.permissionRestriction || passesPermissionRestriction(subItem.permissionRestriction))"
                        class="nav-item"
                        :class="{ active: isActive(subItem.activeUrl || subItem.url) }"
                    >
                        <template v-if="subItem.subItems && subItem.subItems.length">
                            <a
                                class="nav-link"
                                data-bs-toggle="collapse"
                                :href="'#nav-dropdown-' + index + '-' + idx"
                                :aria-expanded="isActive(subItem.activeUrl || subItem.url)"
                            >
                                <span class="sidebar-mini">
                                    <span class="material-icons">remove</span>
                                </span>

                                <span class="sidebar-normal pl-2">
                                    {{ subItem.title }}
                                    <b class="caret"></b>
                                </span>
                            </a>

                            <div
                                class="collapse"
                                :class="{ show: isActive(subItem.activeUrl || subItem.url) }"
                                :id="'nav-dropdown-' + index + '-' + idx"
                            >
                                <ul class="nav">
                                    <template
                                        v-for="(nestedItem, nidx) in subItem.subItems"
                                        :key="nidx"
                                    >
                                        <NavPanelItem
                                            v-if="(!nestedItem.roleRestriction || passesRoleRestriction(nestedItem.roleRestriction)) && (!nestedItem.permissionRestriction || passesPermissionRestriction(nestedItem.permissionRestriction))"
                                            :title="nestedItem.title"
                                            :icon="nestedItem.icon || 'remove'"
                                            :url="nestedItem.url"
                                            :active-url="nestedItem.activeUrl"
                                            :sub-items="nestedItem.subItems"
                                            :sub-item-type="subItemType"
                                            :index="index + '-' + idx + '-' + nidx"
                                            :check-for-updates="checkForUpdates"
                                        />
                                    </template>
                                </ul>
                            </div>
                        </template>

                        <template v-else>
                            <Link class="nav-link" :href="resolveUrl(subItem.url)">
                                <span class="sidebar-mini">
                                    <span class="material-icons">remove</span>
                                </span>

                                <span class="sidebar-normal pl-2">
                                    {{ subItem.title }}
                                </span>
                            </Link>
                        </template>
                    </li>
                </template>
            </ul>
        </div>
    </li>
</template>

<script>
import NavLink from './NavLink.vue';
import { Link } from '@inertiajs/vue3';

export default {
    name: 'NavPanelItem',

    components: {
        NavLink,
        Link,
        NavPanelItem: () => import('./NavPanelItem.vue'),
    },

    props: {
        title: {
            type: String,
            required: true,
        },
        icon: {
            type: String,
            required: true,
        },
        url: {
            type: [String, Function, Object],
            default: null,
        },
        activeUrl: {
            type: [String, Function, Object, Array],
            default: null,
        },
        subItems: {
            type: Array,
            required: false,
        },
        subItemType: {
            type: String,
            default: 'automatic',
        },
        index: {
            type: [Number, String],
            required: true,
        },
        checkForUpdates: {
            type: String,
            default: '',
        },
        show: {
            type: Boolean,
            default: true,
        },
    },

    methods: {
        resolveUrl(value, item = null) {
            if (!value) {
                return '#';
            }

            const resolved = typeof value === 'function'
                ? value(item)
                : value;

            if (typeof resolved === 'string') {
                return resolved;
            }

            return resolved?.url || '#';
        },

        isActive(value) {
            if (!value) {
                return false;
            }

            const currentUrl = this.normalizeUrl(this.$page.url);

            const urls = Array.isArray(value)
                ? value
                : [value];

            return urls.some((url) => {
                const resolvedUrl = this.normalizeUrl(this.resolveUrl(url));

                return currentUrl === resolvedUrl
                    || currentUrl.startsWith(`${resolvedUrl}/`);
            });
        },

        normalizeUrl(url) {
            return String(url || '')
                .split('?')[0]
                .replace(/\/$/, '') || '/';
        },


        passesRoleRestriction(restriction) {
            if (Array.isArray(restriction)) {
                return restriction.some(role => {
                    return this.$page.props.auth.roles[role] === true;
                });
            } else {
                return this.$page.props.auth.roles[restriction] === true;
            }
        },

        passesPermissionRestriction(restriction) {
            if (Array.isArray(restriction)) {
                return restriction.some(permission => {
                    return this.$page.props.auth.permissions[permission] === true;
                });
            } else {
                return this.$page.props.auth.permissions[restriction] === true;
            }
        },
    },
};
</script>

<style>
.sidebar-mini .material-icons {
    font-size: 16px;
}

.sidebar-normal {
    vertical-align: middle;
}

.text-red {
    color: red;
}
</style>
