<template>
    <div
        class="wrapper"
        :class="{ 'nav-open': mobileNavigationOpen }"
        @keydown.esc="mobileNavigationOpen = false"
    >
        <NavPanel id="authenticated-sidebar" />
        <div id="content_wrapper" class="main-panel">
            <NavBar
                :page-title="pageTitle"
                :mobile-navigation-open="mobileNavigationOpen"
                @toggle-mobile-navigation="
                    mobileNavigationOpen = !mobileNavigationOpen
                "
            />
            <div class="content">
                <div class="container-fluid">
                    <slot />
                </div>
            </div>
            <footer v-if="showFooter" class="footer p-0">
                <div
                    class="container-fluid d-flex flex-wrap align-items-center justify-content-center lg:justify-content-between"
                >
                    <nav v-if="scaffold.documentation">
                        <ul>
                            <li>
                                <a :href="scaffold.documentation.href">
                                    {{ scaffold.documentation.label }}
                                </a>
                            </li>
                        </ul>
                    </nav>
                    <div class="copyright">
                        © {{ year }}, made with
                        <i class="material-icons text-danger">favorite</i> by
                        {{ scaffold.author || $page.props.name || 'Laravel' }}.
                    </div>
                </div>
            </footer>
            <button
                v-if="mobileNavigationOpen"
                type="button"
                class="close-layer visible border-0 lg:d-none"
                tabindex="-1"
                aria-label="Aizvērt navigācijas izvēlni"
                @click="mobileNavigationOpen = false"
            ></button>
        </div>
    </div>
</template>

<script>
import NavPanel from './partials/NavPanel.vue';
import NavBar from './partials/NavBar.vue';

export default {
    inject: { scaffold: { default: () => ({}) } },
    components: {
        NavPanel,
        NavBar,
    },
    props: {
        pageTitle: {
            type: String,
            required: false,
        },
        showFooter: {
            type: Boolean,
            required: false,
            default: true,
        },
    },
    data() {
        return {
            year: new Date().getFullYear(),
            mobileNavigationOpen: false,
        };
    },
    computed: {
        errors() {
            return this.$page.props.errors;
        },
    },
    watch: {
        '$page.url'() {
            this.mobileNavigationOpen = false;
        },
        // errors
        errors: {
            async handler() {
                if (this.errors && Object.keys(this.errors).length > 0) {
                    const errors = Object.values(this.errors);
                    const { default: alertify } = await import('alertifyjs');

                    for (const value of errors) {
                        alertify.error(value);
                    }
                }
            },
            deep: true,
        },
        '$page.props.flash': {
            handler() {
                this.showFlashMessages();
            },
            deep: true,
        },
    },

    methods: {
        async showFlashMessages() {
            const flash = this.$page.props.flash || {};
            const { default: alertify } = await import('alertifyjs');

            if (flash.success) {
                alertify.success(flash.success);
            }

            if (flash.message) {
                alertify.message(flash.message);
            }

            if (flash.error) {
                alertify.error(flash.error);
            }

            if (flash.warning) {
                alertify.warning(flash.warning);
            }
        },
    },
    mounted() {
        this.showFlashMessages();
    },
};
</script>

