                    {{ scaffold.author || $page.props.name || 'Laravel' }}
                </div>
            </div>
        </footer>
    </div>
</template>

<script>
import { Link } from '@inertiajs/vue3';
import { register } from '@app/routes';
import backgroundImageUrl from '@scaffold-assets/login.jpg';

export default {
    components: { Link },
    inject: { scaffold: { default: () => ({}) } },
    computed: {
        logoUrl() {
            return this.scaffold.logo;
        },
    },
    data() {
        return {
            year: new Date().getFullYear(),
            backgroundImageUrl,
            appName: this.$page.props.name,
            registrationUrl: register.url(),
        };
    },
    methods: {
        async closeNavigation() {
            const drawer = this.$refs.navigationDrawer;
            const { Drawer } = await import('bootstrap');
            Drawer.getInstance(drawer)?.hide();
        },
    },
};
</script>

