const packagePages = import.meta.glob('./pages/**/*.vue');

export function createScaffoldResolver(localPages = {}) {
    return async (name) => {
        const suffix = `/pages/${name}.vue`;
        const localKey = Object.keys(localPages).find((key) =>
            key.endsWith(suffix),
        );
        const page =
            localKey === undefined
                ? packagePages[`./pages/${name}.vue`]
                : localPages[localKey];

        if (!page) {
            throw new Error(`Page not found: ${name}`);
        }

        const module = typeof page === 'function' ? await page() : page;
        return module.default ?? module;
    };
}
