<template>
    <nav class="navbar navbar-transparent navbar-absolute fixed-top">
        <div
            class="container-fluid d-flex flex-nowrap align-items-center justify-content-between"
        >
            <div class="navbar-wrapper">
                <div class="navbar-minimize">
                    <button
                        type="button"
                        class="btn btn-just-icon btn-white btn-fab btn-round"
                        aria-label="Mainīt sānjoslas platumu"
                        @click="toggleNavPanel"
                    >
                        <i
                            class="material-icons visible-on-sidebar-regular"
                            aria-hidden="true"
                            >more_vert</i
                        >
                        <i
                            class="material-icons visible-on-sidebar-mini"
                            aria-hidden="true"
                            >view_list</i
                        >
                    </button>
                </div>
                <span class="navbar-brand">{{ pageTitle }}</span>
            </div>

            <div class="d-flex align-items-center gap-2">
                <div>
                    <button
                        type="button"
                        class="btn-icon"
                        data-bs-toggle="menu"
                        data-bs-placement="bottom-end"
                        aria-expanded="false"
                        aria-label="Konta izvēlne"
                    >
                        <img
                            v-if="avatarUrl && failedAvatarUrl !== avatarUrl"
                            :src="avatarUrl"
                            class="navbar-avatar"
                            alt=""
                            @error="failedAvatarUrl = avatarUrl"
                        />
                        <i v-else class="material-icons" aria-hidden="true"
                            >person</i
                        >
                    </button>
                    <div class="menu">
                        <Link :href="profileUrl" as="button" class="menu-item"
                            >Mans profils</Link
                        >
                        <Link :href="securityUrl" as="button" class="menu-item"
                            >Konta drošība</Link
                        >
                        <Link
                            :href="userSettingsUrl"
                            as="button"
                            class="menu-item"
                            >Lietotāja iestatījumi</Link
                        >
                        <div class="menu-divider"></div>
                        <Link
                            :href="logoutUrl"
                            method="post"
                            as="button"
                            class="menu-item"
                            >Iziet</Link
                        >
                    </div>
                </div>

                <button
                    type="button"
                    class="btn-icon lg:d-none"
                    aria-controls="authenticated-sidebar"
                    :aria-expanded="mobileNavigationOpen"
                    aria-label="Navigācijas izvēlne"
                    @click="$emit('toggle-mobile-navigation')"
                >
                    <i class="material-icons" aria-hidden="true">menu</i>
                </button>
            </div>
        </div>
    </nav>
</template>

<script>
import { Link } from '@inertiajs/vue3';
import { logout } from '@app/routes';
import { edit as editProfile } from '@app/routes/profile';
import { edit as editSecurity } from '@app/routes/security';
import { index as userSettingsIndex } from '@app/routes/user-settings';

export default {
    name: 'NavBar',
    components: { Link },
    props: {
        pageTitle: String,
        mobileNavigationOpen: Boolean,
    },
    emits: ['toggle-mobile-navigation'],
    data() {
        return {
            logoutUrl: logout.url(),
            userSettingsUrl: userSettingsIndex.url(),
            profileUrl: editProfile.url(),
            securityUrl: editSecurity.url(),
            failedAvatarUrl: '',
        };
    },
    computed: {
        avatarUrl() {
            return this.$page.props.auth.user?.avatar_url;
        },
    },
    methods: {
        toggleNavPanel() {
            document.body.classList.toggle('sidebar-mini');
        },
    },
};
</script>

<style scoped>
.navbar-avatar {
    width: 24px;
    height: 24px;
    border-radius: 50%;
    object-fit: cover;
}
</style>
