import { router } from '@inertiajs/vue3';
import VueTippy from 'vue-tippy';
import 'tippy.js/dist/tippy.css';
import '../fonts/fontawesome-4.7.0.css';
import ClickOutside from './directives/ClickOutsideDirective';
import PausedTyping from './directives/PausedTyping';
import { applyAppearance } from './lib/appearance';
import { initializeFlashToast } from './lib/flashToast';

export function installScaffold(app, options = {}) {
    app.provide('scaffold', options);
    app.directive('focus', {
        mounted(element, binding) {
            if (binding.value !== false) element.focus();
        },
    });
    app.directive('click-outside', ClickOutside);
    app.directive('paused-typing', PausedTyping);
    app.use(VueTippy, {});

    if (!import.meta.env.SSR) {
        router.on('success', (event) =>
            applyAppearance(event.detail.page.props.appearance),
        );
        void import('bootstrap');
        initializeFlashToast();
    }
}
